    choice: Optional[Choice] = None

@dataclass
class Command:
    name: str
    describe: str = ""
    long_desc: str = ""
    version: Optional[str] = None
    aliases: List[str] = field(default_factory=list)
    flag_options: List[Opt] = field(default_factory=list)
    positionals: List[Param] = field(default_factory=list)
    envs: List[EnvDef] = field(default_factory=list)
    subcommands: List['Command'] = field(default_factory=list)
    command_fn: Optional[str] = None
    default_subcommand: Optional[str] = None
    combine_shorts: bool = False
    inherit_flag_options: bool = False
    dotenv: bool = False
    require_tools: List[str] = field(default_factory=list)
