    parent: Optional['Command'] = field(default=None, repr=False)

@dataclass
class ScriptModel:
    root: Command
    functions: Dict[str, List[str]] = field(default_factory=dict)
    source: str = ""
    path: str = ""

@dataclass
class ParseOutcome:
    code: str

# ---------- utilities ----------

def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)

def script_name(path: str) -> str:
    base = os.path.basename(path)
    if base.endswith('.sh'):
        base = base[:-3]
    return base

def sanitize_id(s: str) -> str:
    # Keep case, map non alnum/underscore to underscore.
    return re.sub(r'[^A-Za-z0-9_]', '_', s)

def strip_prefix_name(name: str) -> Tuple[str, bool]:
    if name.startswith('--'):
        return name[2:], False
    if name.startswith('-'):
        return name[1:], False
    if name.startswith('+'):
        return name[1:], True
    return name, False

def id_from_option_name(name: Optional[str]) -> str:
    if not name:
        return ""
    raw, plus = strip_prefix_name(name)
    sid = sanitize_id(raw)
    return ('plus_' + sid) if plus else sid

def default_notation_from_id(opt_id: str) -> str:
    x = opt_id
    if x.startswith('plus_'):
        x = x[5:]
    return sanitize_id(x).upper()

def bash_quote(s: str) -> str:
    if s == "":
        return "''"
    if re.match(r'^[A-Za-z0-9_./:+,=@%^-]+$', s):
        # hyphen is safe inside a word; keep common option-like strings readable.
        return s
    return "'" + s.replace("'", "'\\''") + "'"

def bash_scalar_assign(name: str, value: str, raw: bool=False) -> str:
    if raw:
        return f"{name}={value}"
    return f"{name}={bash_quote(value)}"

def bash_array_assign(name: str, values: List[str]) -> str:
    return f"{name}=(" + (" " + " ".join(bash_quote(v) for v in values) + " " if values else "") + ")"

def bash_assoc_assign(name: str, values: Dict[str, str]) -> str:
    parts = []
    for k, v in values.items():
        # associative array keys are bracketed; quote both defensively
        parts.append(f"[{bash_quote(k)}]={bash_quote(v)}")
    return f"declare -A {name}=(" + (" " + " ".join(parts) + " " if parts else "") + ")"

def heredoc_code(text: str, exit_code: int = 0) -> str:
    return "command cat >&2 <<-'EOF' \n" + text.rstrip('\n') + "\nEOF\nexit " + str(exit_code)

def version_code(name: str, version: Optional[str]) -> str:
    return heredoc_code(f"{name} {version or '0.0.0'}", 0)

def assignments_to_argc_vars(assignments: List[str]) -> str:
    # ARGC_VARS stores semicolon-separated shell assignments, without declare/export.
    compact = []
    for a in assignments:
        if a.startswith('declare -A '):
            compact.append(a[len('declare -A '):])
        elif a.startswith('export '):
            compact.append(a[len('export '):])
        else:
            compact.append(a)
    data = ";".join(compact) + (";" if compact else "")
    return base64.b64encode(data.encode()).decode()

# ---------- source parsing ----------

def extract_functions(text: str) -> Dict[str, List[str]]:
    lines = text.splitlines()
    funcs: Dict[str, List[str]] = {}
    i = 0
    fn_re = re.compile(r'^\s*(?:function\s+)?([A-Za-z_][A-Za-z0-9_:\-\.]*)(?:\s*\(\))?\s*\{')
    while i < len(lines):
        m = fn_re.match(lines[i])
        if not m:
            i += 1
            continue
        name = m.group(1)
        body = []
        # crude brace tracking good enough for examples
        depth = lines[i].count('{') - lines[i].count('}')
        # if one-line function, body may be between braces
        after = lines[i].split('{', 1)[1]
        if '}' in after:
            inner = after.rsplit('}', 1)[0].strip()
            if inner:
                body.append(inner)
            funcs[name] = body
            i += 1
            continue
        i += 1
        while i < len(lines) and depth > 0:
            depth += lines[i].count('{') - lines[i].count('}')
            if depth >= 0:
                if depth == 0 and lines[i].strip() == '}':
                    pass
                else:
                    body.append(lines[i])
            i += 1
        funcs[name] = body
    return funcs

def function_outputs(funcs: Dict[str, List[str]], name: str) -> List[str]:
    body = funcs.get(name, [])
    out: List[str] = []
    i = 0
    while i < len(body):
        line = body[i].strip()
        if not line or line.startswith('#'):
            i += 1
            continue
        # echo VALUE (simple cases)
        if line.startswith('echo '):
            val = line[5:].strip()
            try:
                import shlex
                parts = shlex.split(val)
                out.append(" ".join(parts))
            except Exception:
                out.append(val.strip('"\''))
            i += 1
            continue
        # cat <<-'EOF' / <<EOF here-docs
        if '<<' in line:
            m = re.search(r'<<-?\s*[\'\"]?([A-Za-z0-9_]+)[\'\"]?', line)
            if m:
                end = m.group(1)
                i += 1
                while i < len(body) and body[i].strip() != end:
                    out.append(body[i].lstrip('\t'))
                    i += 1
                if i < len(body):
                    i += 1
                continue
        i += 1
    return out

def apply_long_line(target_meta: dict, line: str):
    key = target_meta.get('_last_key')
    if not key:
        return
    if key == 'describe':
        existing = target_meta.get('long_desc', '')
        target_meta['long_desc'] = (existing + '\n' + line if existing else line)
    elif key == 'cmd':
        existing = target_meta.get('long_desc', '')
        target_meta['long_desc'] = (existing + '\n' + line if existing else line)
    elif key in ('arg', 'option', 'flag', 'env'):
        arr = target_meta.get(key + 's') if key != 'arg' else target_meta.get('args')
        if arr:
            obj = arr[-1]
            if isinstance(obj, (Param, Opt, EnvDef)):
                obj.describe = (obj.describe + '\n' + line) if obj.describe else line

def parse_default_choice(spec: str) -> Tuple[str, Optional[DefaultVal], Optional[Choice]]:
    default = None
    choice = None
    if '[' in spec and spec.endswith(']'):
        pre, inside = spec.split('[', 1)
        inside = inside[:-1]
        spec = pre
        validate = True
        if inside.startswith('?'):
            validate = False
            inside = inside[1:]
        if inside.startswith('='):
            vals = inside[1:].split('|') if inside[1:] else []
            if vals:
                default = DefaultVal('Value', vals[0])
            choice = Choice('Values', vals, True)
        elif inside.startswith('`') and inside.endswith('`'):
            fn = inside[1:-1]
            choice = Choice('Fn', [fn, validate], validate)
        else:
            vals = inside.split('|') if inside else []
            choice = Choice('Values', vals, True)
    return spec, default, choice

def parse_core_modifiers(spec: str) -> Tuple[str, Dict[str, Any]]:
    attrs: Dict[str, Any] = dict(required=False, multiple=False, delimiter=None,
                                 terminated=False, default=None, choice=None,
                                 assigned=False, prefixed=False)
    spec, dflt, choice = parse_default_choice(spec)
    if dflt:
        attrs['default'] = dflt
    if choice:
        attrs['choice'] = choice
    # assigned marker before modifiers/default: --foo:[...]
    if spec.endswith(':'):
        attrs['assigned'] = True
        spec = spec[:-1]
    # explicit default in core: name=value or name=`fn`
    if '=' in spec:
        name, val = spec.split('=', 1)
        spec = name
        if val.startswith('`') and val.endswith('`'):
            attrs['default'] = DefaultVal('Fn', val[1:-1])
        else:
            attrs['default'] = DefaultVal('Value', val)
    if spec.endswith(','):
        attrs['delimiter'] = ','
        spec = spec[:-1]
    if spec.endswith('~'):
        attrs['terminated'] = True
        spec = spec[:-1]
    elif spec.endswith('!'):
        attrs['required'] = True
        spec = spec[:-1]
    elif spec.endswith('*'):
        attrs['multiple'] = True
        spec = spec[:-1]
    elif spec.endswith('+'):
        attrs['multiple'] = True
        attrs['required'] = True
        spec = spec[:-1]
    # prefixed option marker: -X-* leaves -X- after stripping *, so trailing dash
    if (spec.startswith('-') or spec.startswith('+')) and len(spec) > 2 and spec.endswith('-'):
        attrs['prefixed'] = True
        spec = spec[:-1]
    return spec, attrs

def parse_arg(rest: str) -> Param:
    toks = rest.split()
    spec = toks[0] if toks else ''
    rest_toks = toks[1:]
    notation = None
    env = None
    desc_start = 0
    consumed = 0
    for t in rest_toks:
        if t.startswith('$'):
            env = None if t == '$' else t[1:]
            consumed += 1
        elif t.startswith('<') and t.endswith('>'):
            notation = t[1:-1]
            consumed += 1
        else:
            break
    desc = " ".join(rest_toks[consumed:])
    core, attrs = parse_core_modifiers(spec)
    arg_id = core
    if env == '':
        env = None
    if env is None and any(t == '$$' for t in rest_toks[:consumed]):
        env = sanitize_id(arg_id).upper()
    if env == '$':
        env = sanitize_id(arg_id).upper()
    if notation is None:
        notation = core.upper()
    return Param(id=arg_id, describe=desc, notation=notation,
                 required=attrs['required'], multiple=attrs['multiple'],
                 delimiter=attrs['delimiter'], terminated=attrs['terminated'],
                 default=attrs['default'], choice=attrs['choice'], env=env)

def parse_env(rest: str) -> EnvDef:
    toks = rest.split()
    spec = toks[0] if toks else ''
    desc = " ".join(toks[1:])
    core, attrs = parse_core_modifiers(spec)
    return EnvDef(id=core, describe=desc, required=attrs['required'],
                  default=attrs['default'], choice=attrs['choice'])

def parse_option(rest: str, flag: bool=False) -> Opt:
    toks = rest.split()
    name_toks = []
    i = 0
    while i < len(toks) and (toks[i].startswith('-') or toks[i].startswith('+')):
        name_toks.append(toks[i])
        i += 1
    env = None
    notation_toks = []
    while i < len(toks):
        t = toks[i]
        if t.startswith('$'):
            env = t[1:] if t != '$$' else '$$'
            i += 1
        elif t.startswith('<') and t.endswith('>'):
            notation_toks.append(t[1:-1])
            i += 1
        else:
            break
    desc = " ".join(toks[i:])
    if not name_toks:
        name_toks = ['']
    parsed = []
    merged: Dict[str, Any] = dict(required=False, multiple=False, delimiter=None,
                                  terminated=False, default=None, choice=None,
                                  assigned=False, prefixed=False)
    for nt in name_toks:
        clean, attrs = parse_core_modifiers(nt)
        parsed.append(clean)
        for k in ('required','multiple','terminated','assigned','prefixed'):
            merged[k] = merged[k] or attrs[k]
        for k in ('delimiter','default','choice'):
            if attrs[k] is not None:
                merged[k] = attrs[k]
    if len(parsed) >= 2:
        short_name = parsed[0]
        long_name = parsed[-1]
    else:
        short_name = None
        long_name = parsed[0]
    opt_id = id_from_option_name(long_name)
    if env == '$$':
        env = default_notation_from_id(opt_id)
    if flag:
        notations: List[str] = []
        num = (0,0)
        multiple_values = merged['multiple']
        multiple_occurs = merged['multiple']
    else:
        notations = notation_toks[:] if notation_toks else [default_notation_from_id(opt_id)]
        min_n = len(notations)
        max_n = len(notations)
        if notations:
            last = notations[-1]
            if last.endswith('*'):
                min_n = len(notations) - 1
                max_n = INF
            elif last.endswith('+'):
                min_n = len(notations)
                max_n = INF
            elif last.endswith('?'):
                min_n = len(notations) - 1
                max_n = len(notations)
        if merged['terminated']:
            min_n, max_n = 1, INF
        num = (min_n, max_n)
        multiple_occurs = merged['multiple'] or (merged['delimiter'] is not None)
        multiple_values = merged['multiple'] or multiple_occurs or max_n > 1 or len(notations) > 1 or (merged['delimiter'] is not None)
    return Opt(id=opt_id, long_name=long_name or None, short_name=short_name,
               describe=desc, flag=flag, notations=notations,
               required=merged['required'], multiple_values=multiple_values,
               multiple_occurs=multiple_occurs, num_args=num,
               delimiter=merged['delimiter'], terminated=merged['terminated'],
               prefixed=merged['prefixed'], assigned=merged['assigned'],
               default=merged['default'], choice=merged['choice'], env=env)

def parse_symbol(rest: str) -> Optional[SymbolDef]:
    toks = rest.split()
    if not toks:
        return None
    core, attrs = parse_core_modifiers(toks[0])
    if core.startswith('+'):
        sid = sanitize_id(core[1:])
    else:
        sid = sanitize_id(core)
    return SymbolDef(sid, attrs.get('choice'))

def meta_new() -> dict:
    return {'describe':'', 'long_desc':'', 'aliases':[], 'args':[], 'options':[], 'flags':[],
            'envs':[], 'version':None, 'default_subcommand':False, 'combine_shorts':False,
            'inherit_flag_options':False, 'dotenv':False, 'require_tools':[], 'symbol':None,
            '_last_key':None}

def apply_tag(meta: dict, tag: str, rest: str):
    if tag == 'describe':
        meta['describe'] = rest.strip()
        meta['_last_key'] = 'describe'
    elif tag == 'cmd':
        # handled by caller when starting pending command, but allow updates
        meta['describe'] = rest.strip()
        meta['_last_key'] = 'cmd'
    elif tag == 'alias':
        parts = [p.strip() for p in re.split(r'[ ,]+', rest.strip()) if p.strip()]
        meta['aliases'].extend(parts)
        meta['_last_key'] = None
    elif tag == 'arg':
        meta['args'].append(parse_arg(rest))
        meta['_last_key'] = 'arg'
    elif tag == 'option':
        meta['options'].append(parse_option(rest, False))
        meta['_last_key'] = 'option'
    elif tag == 'flag':
        meta['flags'].append(parse_option(rest, True))
        meta['_last_key'] = 'flag'
    elif tag == 'env':
        meta['envs'].append(parse_env(rest))
        meta['_last_key'] = 'env'
    elif tag == 'meta':
        toks = rest.strip().split(None, 1)
        key = toks[0] if toks else ''
        val = toks[1] if len(toks) > 1 else ''
        if key == 'version':
            meta['version'] = val.strip()
        elif key == 'default-subcommand':
            meta['default_subcommand'] = True
        elif key == 'combine-shorts':
            meta['combine_shorts'] = True
        elif key == 'inherit-flag-options':
            meta['inherit_flag_options'] = True
        elif key == 'dotenv':
            meta['dotenv'] = True
        elif key == 'require-tools':
            meta['require_tools'].extend([x for x in re.split(r'[,\s]+', val) if x])
        elif key == 'symbol':
            meta['symbol'] = parse_symbol(val)
        meta['_last_key'] = None

def update_command_from_meta(cmd: Command, meta: dict):
    cmd.describe = meta.get('describe','')
    cmd.long_desc = meta.get('long_desc','')
    # automatic hyphen alias for underscores
    auto = cmd.name.replace('_','-')
    aliases = []
    if auto != cmd.name:
        aliases.append(auto)
    aliases.extend(meta.get('aliases', []))
    # de-duplicate, skip primary
    seen = set()
    cmd.aliases = []
    for a in aliases:
        if a != cmd.name and a not in seen:
            cmd.aliases.append(a); seen.add(a)
    cmd.positionals = meta.get('args', [])
    cmd.flag_options = meta.get('flags', []) + meta.get('options', [])
    cmd.envs = meta.get('envs', [])
    cmd.version = meta.get('version')
    cmd.combine_shorts = meta.get('combine_shorts', False)
    cmd.inherit_flag_options = meta.get('inherit_flag_options', False)
    cmd.dotenv = meta.get('dotenv', False)
    cmd.require_tools = meta.get('require_tools', [])
    if meta.get('symbol'):
        cmd.symbol = meta.get('symbol')

def find_subcommand(parent: Command, name: str) -> Optional[Command]:
    for c in parent.subcommands:
        if c.name == name or name in c.aliases:
            return c
    return None

def add_command(root: Command, fn: str, meta: dict):
    parts = fn.split('::')
    parent = root
    full_parts = []
    for idx, part in enumerate(parts):
        full_parts.append(part)
        cmd = None
        for c in parent.subcommands:
            if c.name == part:
                cmd = c; break
        if cmd is None:
            cmd = Command(name=part, parent=parent)
            auto = part.replace('_','-')
            if auto != part:
                cmd.aliases.append(auto)
            parent.subcommands.append(cmd)
        if idx == len(parts)-1:
            update_command_from_meta(cmd, meta)
            cmd.command_fn = fn
            if meta.get('default_subcommand'):
                parent.default_subcommand = cmd.name
        parent = cmd

def parse_script(path: str) -> ScriptModel:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        text = ''
    root = Command(name=script_name(path))
    funcs = extract_functions(text)
    root_meta = meta_new()
    pending: Optional[dict] = None
    tag_re = re.compile(r'^\s*#\s*@([A-Za-z][A-Za-z0-9_-]*)\b\s*(.*)$')
    comment_re = re.compile(r'^\s*#\s?(.*)$')
    fn_re = re.compile(r'^\s*(?:function\s+)?([A-Za-z_][A-Za-z0-9_:\-\.]*)(?:\s*\(\))?\s*\{')
    lines = text.splitlines()
    for line in lines:
        mt = tag_re.match(line)
        if mt:
            tag, rest = mt.group(1), mt.group(2)
            if tag == 'cmd':
                pending = meta_new()
                apply_tag(pending, tag, rest)
            else:
                apply_tag(pending if pending is not None else root_meta, tag, rest)
            continue
        mc = comment_re.match(line)
        if mc:
            content = mc.group(1)
            apply_long_line(pending if pending is not None else root_meta, content)
            continue
        mf = fn_re.match(line)
        if mf:
            fn = mf.group(1)
            if pending is not None:
                add_command(root, fn, pending)
                pending = None
            elif fn == 'main':
                root.command_fn = 'main'
            continue
        # A non-comment, non-function line ends the last long-line target for root,
        # but keep pending @cmd across blank/non-code only if it has not yet met a fn.
        if pending is None:
            root_meta['_last_key'] = None
    update_command_from_meta(root, root_meta)
    # update_command_from_meta overwrote root.subcommands; restore? It does not touch subcommands.
    if 'main' in funcs and root.command_fn is None and not root.subcommands:
        root.command_fn = 'main'
    return ScriptModel(root=root, functions=funcs, source=text, path=path)

# ---------- model helpers ----------

def command_path(cmd: Command) -> List[Command]:
    arr = []
    while cmd is not None:
        arr.append(cmd)
        cmd = cmd.parent
    return list(reversed(arr))

def display_path(cmd: Command) -> str:
    return " ".join(c.name for c in command_path(cmd))

def all_alias_names(parent: Command) -> List[str]:
    names=[]
    for c in parent.subcommands:
        names.append(c.name)
        names.extend(c.aliases)
    return names

def implicit_help_long(cmd: Command) -> str:
    # one-hyphen help for commands whose options are one-hyphen/plus only
    user = cmd.flag_options
    if user and not any((o.long_name or '').startswith('--') for o in user):
        return '-help'
    return '--help'

def make_help_opt(cmd: Command, describe: str = "Print help") -> Opt:
    return Opt(id='help', long_name=implicit_help_long(cmd), short_name='-h', describe=describe,
               flag=True, num_args=(0,0))

def make_version_opt() -> Opt:
    return Opt(id='version', long_name='--version', short_name='-V', describe='Print version',
               flag=True, num_args=(0,0))

def root_user_options(root: Command) -> List[Opt]:
    return root.flag_options

def effective_options(cmd: Command, root: Command) -> List[Opt]:
    opts = list(cmd.flag_options)
    if cmd is not root and root.inherit_flag_options:
        inherited=[]
        for o in root.flag_options:
            import copy
            no=copy.copy(o); no.inherited=True
            inherited.append(no)
        # original help shows inherited before command options; examples have no command opts
        opts = inherited + opts
    return opts

def command_combine_shorts(cmd: Command, root: Command) -> bool:
    return cmd.combine_shorts or root.combine_shorts

def option_names(opt: Opt) -> List[str]:
    names=[]
    if opt.long_name: names.append(opt.long_name)
    if opt.short_name: names.append(opt.short_name)
    return names

def find_option_by_token(opts: List[Opt], token: str) -> Tuple[Optional[Opt], Optional[str], Optional[str], bool]:
    # returns (opt, matched_name, assigned_value, is_prefixed)
    for o in opts:
        if o.prefixed:
            for nm in option_names(o):
                if nm and token.startswith(nm) and token != nm:
                    return o, nm, None, True
            continue
        for nm in option_names(o):
            if not nm:
                continue
            if token == nm:
                return o, nm, None, False
            if token.startswith(nm + '='):
                return o, nm, token[len(nm)+1:], False
    return None, None, None, False

def is_recognized_option_start(opts: List[Opt], token: str) -> bool:
    o, _, _, _ = find_option_by_token(opts, token)
    return o is not None

def is_option_like(tok: str) -> bool:
    return (tok.startswith('-') and tok != '-') or (tok.startswith('+') and tok != '+')

def split_delim(values: List[str], delim: Optional[str]) -> List[str]:
    if not delim:
        return values
    out=[]
    for v in values:
        out.extend(v.split(delim))
    return out

def default_to_runtime(default: DefaultVal) -> Tuple[str, bool]:
    if default.kind == 'Fn':
        return f'`{default.value}`', True
    return default.value, False

def choice_values(choice: Optional[Choice], funcs: Dict[str, List[str]]) -> Tuple[List[str], bool]:
    if not choice:
        return [], False
    if choice.kind == 'Values':
        return list(choice.data), True
    if choice.kind == 'Fn':
        fn = choice.data[0] if isinstance(choice.data, list) else choice.data
        return function_outputs(funcs, fn), bool(choice.validate)
    return [], False

def validate_choice(label: str, value: str, choice: Optional[Choice], funcs: Dict[str, List[str]], env_label: bool=False) -> Optional[str]:
    vals, do_val = choice_values(choice, funcs)
    if not choice or not do_val:
        return None
    if value not in vals:
        poss = ", ".join(vals)
        if env_label:
            return f"error: invalid value `{value}` for environment variable `{label}`\n  [possible values: {poss}]"
        return f"error: invalid value `{value}` for `{label}`\n  [possible values: {poss}]"
    return None

def opt_value_label(opt: Opt, required_override: Optional[bool]=None) -> str:
    if opt.assigned:
        return f"{opt.long_name}=<{opt.notations[0] if opt.notations else default_notation_from_id(opt.id)}>"
    if opt.prefixed:
        return f"{opt.long_name} <{opt.notations[0] if opt.notations else default_notation_from_id(opt.id)}>"
    name = opt.long_name or opt.short_name or opt.id
    n = opt.notations[0] if opt.notations else default_notation_from_id(opt.id)
    if opt.multiple_occurs and opt.required:
        return f"{name} <{n}>..."
    return f"{name} <{n}>"

def opt_choice_label(opt: Opt) -> str:
    return f"<{opt.notations[0] if opt.notations else default_notation_from_id(opt.id)}>"

def positional_usage(p: Param) -> str:
    n = p.notation or p.id.upper()
    if p.terminated:
        return f"[{n}]..."
    if p.multiple:
        return f"<{n}>..." if p.required else f"[{n}]..."
    return f"<{n}>" if p.required else f"[{n}]"

def required_usage_for_opt(o: Opt) -> str:
    name = o.long_name or o.short_name or o.id
    n = o.notations[0] if o.notations else default_notation_from_id(o.id)
    if o.assigned:
        return f"{name}=<{n}>"
    if o.multiple_occurs or o.multiple_values:
        return f"{name} <{n}>..."
    return f"{name} <{n}>"

# ---------- help generation ----------

def wrap_paragraph(text: str, width: int, initial: str='', subsequent: str='') -> List[str]:
    if text == '':
        return [initial.rstrip()]
    lines=[]
    for para in text.split('\n'):
        if para == '':
            lines.append('')
        else:
            lines.extend(textwrap.wrap(para, width=width, initial_indent=initial,
                                       subsequent_indent=subsequent, break_long_words=False,
                                       break_on_hyphens=False) or [initial.rstrip()])
    return lines

def format_description(cmd: Command, width: int) -> List[str]:
    text = cmd.describe or ''
    if cmd.long_desc:
        text = (text + '\n\n' + cmd.long_desc) if text else cmd.long_desc
    if not text:
        return []
    return wrap_paragraph(text, width)

def opt_display(o: Opt) -> str:
    if o.flag:
        ln = o.long_name or ''
        if o.multiple_occurs:
            ln = ln + '...'
        if o.short_name:
            if ln:
                return f"{o.short_name}, {ln}"
            return o.short_name
        return ln
    n = o.notations[0] if o.notations else default_notation_from_id(o.id)
    if o.prefixed:
        val = f"[{n}]..." if (o.multiple_values or o.multiple_occurs) else f"<{n}>"
        base = o.long_name or ''
        if o.short_name:
            return f"{o.short_name}, {base} {val}"
        return f"{base} {val}"
    if o.assigned:
        val = f"=<{n}>"
    elif len(o.notations) > 1:
        val = " " + " ".join(f"<{x}>" for x in o.notations)
    elif o.num_args[1] == INF and (o.notations and (o.notations[-1].endswith('*') or o.notations[-1].endswith('+'))):
        val = f" <{n}>"
    elif o.num_args[0] == 0 and o.num_args[1] == 1 and (o.notations and o.notations[-1].endswith('?')):
        val = f" <{n}>"
    elif o.terminated:
        val = f" <{n}~>" if not n.endswith('~') else f" <{n}>"
    elif o.multiple_occurs:
        val = f" <{n}>..." if o.required else f" [{n}]..."
    else:
        val = f" <{n}>"
    ln = (o.long_name or '') + val
    if o.short_name:
        return f"{o.short_name}, {ln}"
    return ln

def static_details(desc: str, choice: Optional[Choice], default: Optional[DefaultVal], env: Optional[str]) -> str:
    parts=[]
    if desc:
        parts.append(desc)
    if choice and choice.kind == 'Values':
        parts.append('[possible values: ' + ', '.join(choice.data) + ']')
    if default and default.kind == 'Value':
        parts.append('[default: ' + default.value + ']')
    if env:
        parts.append('[env: ' + env + ']')
    return ' '.join(parts)

def format_table(rows: List[Tuple[str,str]], width: int, indent: str='  ') -> List[str]:
    if not rows:
        return []
    leftw = max(len(r[0]) for r in rows)
    leftw = min(leftw, 46)
    lines=[]
    for left, desc in rows:
        if not desc:
            lines.append(f"{indent}{left}")
            continue
        prefix = f"{indent}{left:<{leftw}}  "
        sub = " " * len(prefix)
        wrapped = wrap_paragraph(desc, max(20, width-len(prefix)), prefix, sub)
        lines.extend(wrapped)
    return lines

def help_text(model: ScriptModel, cmd: Command) -> str:
    root = model.root
    width = int(os.environ.get('TERM_WIDTH') or os.environ.get('COLUMNS') or '80')
    lines: List[str] = []
    desc_lines = format_description(cmd, width)
    if desc_lines:
        lines.extend(desc_lines)
        lines.append('')
    # usage
    usage = f"USAGE: {display_path(cmd)}"
    opts = effective_options(cmd, root)
    has_user_opts = bool(opts)
    if has_user_opts:
        usage += " [OPTIONS]"
    if cmd.subcommands:
        usage += " <COMMAND>"
    else:
        for o in opts:
            if o.required:
                usage += " " + required_usage_for_opt(o)
        for p in cmd.positionals:
            usage += " " + positional_usage(p)
    lines.append(usage)
    # args (root with subcommands can still show args in original help)
    if cmd.positionals:
        lines.append('')
        lines.append('ARGS:')
        rows=[]
        for p in cmd.positionals:
            rows.append((positional_usage(p), static_details(p.describe, p.choice, p.default, p.env)))
        lines.extend(format_table(rows, width))
    # options: show if user opts; include implicit help/version when user opts or root no subcommands? root with user opts yes
    if has_user_opts:
        lines.append('')
        lines.append('OPTIONS:')
        rows=[]
        for o in opts:
            rows.append((opt_display(o), static_details(o.describe, o.choice, o.default, o.env)))
        # implicit help
        rows.append((opt_display(make_help_opt(cmd)), 'Print help' if (cmd is root or has_user_opts) else ''))
        if cmd is root:
            rows.append((opt_display(make_version_opt()), 'Print version'))
        lines.extend(format_table(rows, width))
    # envs
    envs = []
    if cmd is root:
        envs = root.envs[:]
    else:
        # root envs except overridden by command envs, then command envs
        overridden = {e.id for e in cmd.envs}
        envs = [e for e in root.envs if e.id not in overridden] + cmd.envs
    if envs:
        lines.append('')
        lines.append('ENVIRONMENTS:')
        rows=[]
        for e in envs:
            left = e.id + ('*' if e.required else '')
            rows.append((left, static_details(e.describe, e.choice, e.default, None)))
        lines.extend(format_table(rows, width))
    if cmd.subcommands:
        lines.append('')
        lines.append('COMMANDS:')
        rows=[]
        for c in cmd.subcommands:
            left = c.name
            desc = c.describe
            tags=[]
            if cmd.default_subcommand == c.name:
                tags.append('default')
            if c.aliases:
                tags.append('aliases: ' + ', '.join(c.aliases))
            if tags:
                desc = (desc + ' ' if desc else '') + '[' + '] ['.join(tags) + ']'
            rows.append((left, desc))
        lines.extend(format_table(rows, width))
    return "\n".join(lines).rstrip() + "\n"

# ---------- environment/default validation ----------

def load_dotenv_if_needed(model: ScriptModel):
    if not model.root.dotenv:
        return
    p = os.path.join(os.getcwd(), '.env')
    if not os.path.exists(p):
        return
    try:
        with open(p, 'r', encoding='utf-8') as f:
            for line in f:
                line=line.strip()
                if not line or line.startswith('#') or '=' not in line:
                    continue
                k,v=line.split('=',1)
                if k not in os.environ:
                    os.environ[k]=v
    except Exception:
        pass

def env_assignments(model: ScriptModel, cmd: Command) -> Union[List[str], str]:
    load_dotenv_if_needed(model)
    envs = model.root.envs[:]
    if cmd is not model.root:
        # command env overrides same-name root env for validation/default
        by = {e.id:e for e in envs}
        order = [e.id for e in envs]
        for e in cmd.envs:
            if e.id not in by:
                order.append(e.id)
            by[e.id] = e
        envs = [by[k] for k in order]
    missing=[]
    assigns=[]
    for e in envs:
        val = os.environ.get(e.id)
        raw=False
        if (val is None or val == '') and e.default:
            val, raw = default_to_runtime(e.default)
            assigns.append(f"export {bash_scalar_assign(e.id, val, raw)}")
        elif val is not None and val != '':
            # already exported by parent; validate
            pass
        elif e.required:
            missing.append(e.id)
        if val is not None and val != '' and e.choice:
            msg = validate_choice(e.id, val, e.choice, model.functions, env_label=True)
            if msg:
                return msg
    if missing:
        return "error: the following required environments were not provided:\n" + "\n".join(f"  {m}" for m in missing)
    return assigns

def check_required_tools(cmd: Command, root: Command) -> Optional[str]:
    tools=[]
    tools.extend(root.require_tools)
    if cmd is not root:
        tools.extend(cmd.require_tools)
    missing=[t for t in tools if t and shutil.which(t) is None]
    if missing:
        return "error: missing tools: " + ",".join(missing)
    return None

# ---------- parsing invocation ----------

class Parser:
    def __init__(self, model: ScriptModel, argv: List[str]):
        self.model = model
        self.root = model.root
        self.argv = argv
        self.assigns: List[str] = []
        self.values: Dict[str, Any] = {}
        self.positionals: List[str] = []
        self.cmd: Command = self.root
        self.command_arg_index = 0
        self.stop_options = False
        self.root_opts_values: Dict[str, Any] = {}

    def error(self, msg: str) -> ParseOutcome:
        return ParseOutcome(heredoc_code(msg, 1))

    def help(self, cmd: Command) -> ParseOutcome:
        return ParseOutcome(heredoc_code(help_text(self.model, cmd), 0))

    def version(self) -> ParseOutcome:
        return ParseOutcome(version_code(self.root.name, self.root.version))

    def parse(self) -> ParseOutcome:
        # dotenv/envs are validated after final command is known, but root envs can fail even for help? Original help ignores env required.
        # Select command first, with root options before commands.
        args = list(self.argv)
        # root help/version before everything
        if args and args[0] in ('--help','-h','-help'):
            return self.help(self.root)
        if args and args[0] in ('--version','-V'):
            return self.version()
        # symbol prefix
        if self.root.symbol and args and args[0].startswith('+') and len(args[0]) > 1:
            symval = args.pop(0)[1:]
            self.values['argc_' + self.root.symbol.id] = symval
        # Root options before command for subcommand CLIs
        if self.root.subcommands:
            # parse root options until command/non-option
            root_opts = self.root.flag_options
            consumed_args=[]
            i=0
            while i < len(args):
                tok=args[i]
                if tok in ('--help','-h','-help'):
                    return self.help(self.root)
                if tok in ('--version','-V'):
                    return self.version()
                o,nm,aval,pref = find_option_by_token(root_opts, tok)
                if o:
                    res, ni = self.consume_option(o, args, i, root_opts, self.root_opts_values)
                    if isinstance(res, str):
                        return self.error(res)
                    i = ni
                    continue
                if is_option_like(tok):
                    # unknown option before command
                    return self.error(f"error: unexpected argument `{tok}` found")
                # command token or default
                break
            args = args[i:]
            cmd = self.root
            while cmd.subcommands:
                if not args:
                    if cmd.default_subcommand:
                        d=find_subcommand(cmd, cmd.default_subcommand)
                        if d:
                            cmd=d
                            break
                    return self.help(cmd)
                tok=args[0]
                if tok in ('--help','-h','-help'):
                    return self.help(cmd)
                found=find_subcommand(cmd, tok)
                if found:
                    cmd=found
                    args=args[1:]
                    continue
                if cmd.default_subcommand:
                    d=find_subcommand(cmd, cmd.default_subcommand)
                    if d:
                        cmd=d
                        break
                if is_option_like(tok):
                    return self.error(f"error: unexpected argument `{tok}` found")
                subs=', '.join(all_alias_names(cmd))
                return self.error(f"error: `{display_path(cmd).replace(' ', '-')}` requires a subcommand but '{tok}' is not one of them\n  [subcommands: {subs}]")
            self.cmd=cmd
        else:
            self.cmd=self.root
        # If final command still has subcommands (parent selected without child), show help
        if self.cmd.subcommands:
            return self.help(self.cmd)
        # Parse command args/options
        # Terminal positional commands deliberately treat help flags as data.
        terminal_pos = any(p.terminated for p in self.cmd.positionals)
        if not terminal_pos:
            if args and args[0] in ('--help','-h','-help'):
                return self.help(self.cmd)
            if self.cmd is self.root and args and args[0] in ('--version','-V'):
                return self.version()
        res = self.parse_options_and_positionals(args)
        if isinstance(res, ParseOutcome):
            return res
        # Required tools (help already returned)
        msg = check_required_tools(self.cmd, self.root)
        if msg:
            return self.error(msg)
        envres = env_assignments(self.model, self.cmd)
        if isinstance(envres, str):
            return self.error(envres)
        self.assigns.extend(envres)
        # Build success shell code
        return ParseOutcome(self.success_code())

    def consume_option(self, opt: Opt, args: List[str], i: int, opts: List[Opt], store: Dict[str, Any]) -> Tuple[Union[None,str], int]:
        tok=args[i]
        o,nm,aval,pref = find_option_by_token([opt], tok)
        var='argc_' + opt.id
        if opt.prefixed:
            # key is suffix after matched prefix; value after '=' or next arg or 1
            suffix = tok[len(nm):] if nm else ''
            key=suffix; val='1'; ni=i+1
            if '=' in suffix:
                key,val=suffix.split('=',1)
            elif i+1 < len(args) and not is_option_like(args[i+1]):
                val=args[i+1]; ni=i+2
            msg=validate_choice(opt_choice_label(opt), val, opt.choice, self.model.functions)
            if msg: return msg, i
            d=store.setdefault(var,{})
            if not isinstance(d, dict): d={}
            d[key]=val; store[var]=d
            return None, ni
        if opt.flag:
            if aval is not None:
                return f"error: flag `{opt.long_name or nm}` don't accept any value", i
            if var in store and not opt.multiple_occurs:
                return f"error: the argument `{opt.long_name or nm}` cannot be used multiple times", i
            if opt.multiple_occurs:
                store[var]=int(store.get(var,0))+1
            else:
                store[var]='1'
            return None, i+1
        if var in store and not opt.multiple_occurs:
            return f"error: the argument `{opt.long_name or nm}` cannot be used multiple times", i
        if opt.assigned and aval is None:
            return f"error: incorrect number of values for `{opt.long_name}=<{opt.notations[0] if opt.notations else default_notation_from_id(opt.id)}>`", i
        vals=[]
        ni=i+1
        if aval is not None:
            vals.append(aval)
        if opt.terminated:
            if aval is None:
                vals.extend(args[i+1:]); ni=len(args)
            else:
                vals.extend(args[i+1:]); ni=len(args)
            if len(vals) < opt.num_args[0]:
                return f"error: incorrect number of values for `{opt_value_label(opt)}`", i
        elif opt.assigned:
            pass
        else:
            min_n,max_n=opt.num_args
            # consume remaining required/flexible values
            while len(vals) < max_n and ni < len(args):
                nxt=args[ni]
                if len(vals) >= min_n and is_recognized_option_start(opts, nxt):
                    break
                if max_n == INF and len(vals) >= min_n and is_option_like(nxt) and is_recognized_option_start(opts, nxt):
                    break
                # For variable arity, stop at recognized option. Unknown option-like is left for later error if user opts exist.
                if max_n == INF and len(vals) >= min_n and is_option_like(nxt) and is_recognized_option_start(opts, nxt):
                    break
                if max_n == INF and len(vals) >= min_n and is_option_like(nxt) and any(True for _ in opts) and is_recognized_option_start(opts, nxt):
                    break
                if max_n == INF and is_recognized_option_start(opts, nxt):
                    break
                if len(vals) >= min_n and max_n == INF and is_option_like(nxt) and is_recognized_option_start(opts, nxt):
                    break
                if max_n == INF and is_option_like(nxt) and is_recognized_option_start(opts, nxt):
                    break
                # optional value stops before any recognized option; otherwise consumes one positional-like token.
                vals.append(nxt); ni+=1
                if max_n != INF and len(vals) >= max_n:
                    break
            if len(vals) < min_n:
                return f"error: incorrect number of values for `{opt_value_label(opt)}`", i
        vals = split_delim(vals, opt.delimiter)
        for v in vals:
            msg=validate_choice(opt_choice_label(opt), v, opt.choice, self.model.functions)
            if msg: return msg, i
        if opt.multiple_values:
            old=store.get(var, [])
            if not isinstance(old, list): old=[old]
            old.extend(vals)
            store[var]=old
        else:
            store[var]=vals[0] if vals else ''
        return None, ni

    def parse_options_and_positionals(self, args: List[str]) -> Optional[ParseOutcome]:
        opts=effective_options(self.cmd, self.root)
        # seed root option values parsed before command (inherit/global)
        store=dict(self.root_opts_values)
        pos=[]
        user_opts_exist=bool(opts)
        i=0
        combine = command_combine_shorts(self.cmd, self.root)
        terminal_pos = any(p.terminated for p in self.cmd.positionals)
        while i < len(args):
            tok=args[i]
            if tok == '--':
                pos.extend(args[i+1:]); break
            if not terminal_pos and tok in ('--help','-h','-help'):
                return self.help(self.cmd)
            if self.cmd is self.root and tok in ('--version','-V'):
                return self.version()
            # combine short flags like -rf / -ee only for single-character short flags
            if combine and re.match(r'^-[A-Za-z]{2,}$', tok):
                chars=tok[1:]
                ok=True; expanded=[]
                for ch in chars:
                    match=None
                    for o in opts:
                        if o.flag and o.short_name == '-' + ch:
                            match=o; break
                    if not match:
                        ok=False; break
                    expanded.append(match)
                if ok:
                    for o in expanded:
                        var='argc_'+o.id
                        if var in store and not o.multiple_occurs:
                            return self.error(f"error: the argument `{o.long_name or o.short_name}` cannot be used multiple times")
                        if o.multiple_occurs:
                            store[var]=int(store.get(var,0))+1
                        else:
                            store[var]='1'
                    i+=1; continue
                else:
                    return self.error(f"error: unexpected argument `{tok}` found")
            o,nm,aval,pref=find_option_by_token(opts, tok)
            if o:
                res,ni=self.consume_option(o,args,i,opts,store)
                if isinstance(res,str): return self.error(res)
                i=ni; continue
            if is_option_like(tok) and user_opts_exist:
                return self.error(f"error: unexpected argument `{tok}` found")
            pos.append(tok); i+=1
        # apply env/defaults for options
        missing=[]
        for o in opts:
            var='argc_'+o.id
            if var not in store:
                # env binding
                if o.env and os.environ.get(o.env) not in (None,''):
                    ev=os.environ.get(o.env,'')
                    vals=split_delim([ev], o.delimiter)
                    if o.flag:
                        store[var]=ev
                    elif o.multiple_values:
                        store[var]=vals
                    else:
                        store[var]=vals[0] if vals else ''
                elif o.default:
                    val, raw=default_to_runtime(o.default)
                    store[var]=(val, raw)
                elif o.required:
                    missing.append(required_usage_for_opt(o))
            # validate env/default static values if present
            if var in store and o.choice:
                sv=store[var]
                vals=[]
                if isinstance(sv, tuple):
                    vals=[]  # dynamic shell default: skip validation here
                elif isinstance(sv, list): vals=sv
                elif isinstance(sv, dict): vals=list(sv.values())
                else: vals=[str(sv)]
                for v in vals:
                    msg=validate_choice(opt_choice_label(o), v, o.choice, self.model.functions)
                    if msg: return self.error(msg)
        if missing:
            return self.error("error: the following required arguments were not provided:\n" + "\n".join(f"  {m}" for m in missing))
        self.values.update(store)
        # positionals
        pres=self.assign_positionals(pos)
        if isinstance(pres, str):
            return self.error(pres)
        return None

    def assign_positionals(self, pos: List[str]) -> Optional[str]:
        specs=self.cmd.positionals
        final=[]
        if not specs:
            self.positionals=pos[:]
            return None
        idx=0
        values_by_var: Dict[str, Any]={}
        missing=[]
        for si,p in enumerate(specs):
            var='argc_'+sanitize_id(p.id)
            remaining_specs=len(specs)-si-1
            if p.terminated:
                vals=pos[idx:]; idx=len(pos)
                vals=split_delim(vals,p.delimiter)
                if vals:
                    values_by_var[var]=vals
                    final.extend(vals)
                continue
            if p.multiple:
                # leave one token for each remaining positional when possible
                take=max(0, len(pos)-idx-remaining_specs)
                vals=pos[idx:idx+take]; idx+=take
                vals=split_delim(vals,p.delimiter)
                if not vals and p.env and os.environ.get(p.env) not in (None,''):
                    vals=split_delim([os.environ.get(p.env,'')], p.delimiter)
                if not vals and p.required:
                    missing.append(positional_usage(p))
                if vals:
                    for v in vals:
                        msg=validate_choice(positional_usage(p), v, p.choice, self.model.functions)
                        if msg: return msg
                    values_by_var[var]=vals
                    final.extend(vals)
            else:
                val=None; raw=False
                if idx < len(pos):
                    val=pos[idx]; idx+=1
                elif p.env and os.environ.get(p.env) not in (None,''):
                    val=os.environ.get(p.env,'')
                elif p.default:
                    val,raw=default_to_runtime(p.default)
                elif p.required:
                    missing.append(positional_usage(p))
                if val is not None:
                    if not raw:
                        msg=validate_choice(positional_usage(p), val, p.choice, self.model.functions)
                        if msg: return msg
                    values_by_var[var]=(val, raw) if raw else val
                    final.append(val)
        if missing:
            return "error: the following required arguments were not provided:\n" + "\n".join(f"  {m}" for m in missing)
        if idx < len(pos):
            return f"error: unexpected argument `{pos[idx]}` found"
        self.values.update(values_by_var)
        self.positionals=final
        return None

    def success_code(self) -> str:
        root=self.root; cmd=self.cmd
        assigns=[]
        # Values assignments in insertion-ish order: current self.values already in parse order mostly; sort? Preserve dict insertion.
        for var,val in self.values.items():
            if isinstance(val, tuple):
                v,raw=val; assigns.append(bash_scalar_assign(var,v,raw))
            elif isinstance(val, list):
                assigns.append(bash_array_assign(var,val))
            elif isinstance(val, dict):
                assigns.append(bash_assoc_assign(var,val))
            else:
                assigns.append(bash_scalar_assign(var,str(val)))
        # special core vars
        allargs=[root.name]+self.argv
        assigns.append(bash_array_assign('argc__args', allargs))
        if cmd.command_fn or cmd.command_fn == 'main':
            fn = cmd.command_fn if cmd.command_fn else None
        else:
            fn = cmd.command_fn
        # root main
        if cmd is root and root.command_fn:
            fn=root.command_fn
        if fn:
            assigns.append(bash_scalar_assign('argc__fn', fn))
        assigns.append(bash_array_assign('argc__positionals', self.positionals))
        all_assigns = self.assigns + assigns
        lines=[]
        lines.append('export ARGC_VARS=' + assignments_to_argc_vars(all_assigns))
        lines.extend(self.assigns)
        lines.extend(assigns)
        lines.append(PARALLEL_FUNC)
        if fn:
            lines.append('if [[ "$(type -t _argc_before 2>/dev/null)" == function ]]; then _argc_before; fi')
            lines.append(f"{bash_quote(fn)} \"${{argc__positionals[@]}}\"")
            lines.append('if [[ "$(type -t _argc_after 2>/dev/null)" == function ]]; then _argc_after; fi')
        return "\n".join(lines)

PARALLEL_FUNC = r'''argc() {
    if [[ "$1" == "--argc-parallel" ]]; then
        shift
        local __argc_file="$1"
        shift
        local -a __argc_groups=()
        local __argc_cur=""
        local __argc_word
        for __argc_word in "$@"; do
            if [[ "$__argc_word" == ":::" ]]; then
                __argc_groups+=("$__argc_cur")
                __argc_cur=""
            else
                if [[ -z "$__argc_cur" ]]; then __argc_cur="$__argc_word"; else __argc_cur="$__argc_cur
$__argc_word"; fi
            fi
        done
        __argc_groups+=("$__argc_cur")
        local __argc_tmp="${TMPDIR:-/tmp}/argc_parallel_$$"
        mkdir -p "$__argc_tmp"
        local -a __argc_pids=()
        local __argc_i=0
        for __argc_cur in "${__argc_groups[@]}"; do
            (
                local -a __argc_cmd=()
                while IFS= read -r __argc_word; do __argc_cmd+=("$__argc_word"); done <<< "$__argc_cur"
                "${__argc_cmd[@]}"
            ) >"$__argc_tmp/out.$__argc_i" 2>"$__argc_tmp/err.$__argc_i" &
            __argc_pids+=("$!")
            __argc_i=$((__argc_i+1))
        done
        local __argc_status=0
        for __argc_word in "${__argc_pids[@]}"; do wait "$__argc_word" || __argc_status=$?; done
        for ((__argc_i=0; __argc_i<${#__argc_groups[@]}; __argc_i++)); do cat "$__argc_tmp/out.$__argc_i"; done
        for ((__argc_i=0; __argc_i<${#__argc_groups[@]}; __argc_i++)); do cat "$__argc_tmp/err.$__argc_i" >&2; done
        rm -rf "$__argc_tmp"
        return $__argc_status
    else
        command argc "$@"
    fi
