# ---------- JSON export ----------

def default_json(d: Optional[DefaultVal]):
    if not d: return None
    return {'type': d.kind, 'value': d.value}

def choice_json(c: Optional[Choice]):
    if not c: return None
    if c.kind == 'Values': return {'type':'Values','data':c.data}
    return {'type':'Fn','data':c.data}

def opt_json(o: Opt):
    return {
        'id': o.id, 'long_name': o.long_name, 'short_name': o.short_name,
        'describe': o.describe, 'flag': o.flag, 'notations': o.notations,
        'required': o.required, 'multiple_values': o.multiple_values,
        'multiple_occurs': o.multiple_occurs, 'num_args': list(o.num_args),
        'delimiter': o.delimiter, 'terminated': o.terminated,
        'prefixed': o.prefixed, 'assigned': o.assigned,
        'default': default_json(o.default), 'choice': choice_json(o.choice),
        'env': o.env, 'inherited': o.inherited,
    }

def param_json(p: Param):
    return {'id': p.id, 'describe': p.describe, 'notation': p.notation,
            'required': p.required, 'multiple': p.multiple,
            'delimiter': p.delimiter, 'terminated': p.terminated,
            'default': default_json(p.default), 'choice': choice_json(p.choice), 'env': p.env}

def env_json(e: EnvDef):
    return {'id': e.id, 'describe': e.describe, 'required': e.required,
            'default': default_json(e.default), 'choice': choice_json(e.choice)}

def cmd_json(cmd: Command, root: Command):
    fos=[opt_json(o) for o in cmd.flag_options]
    # implicit options in export
    if cmd is root:
        h=make_help_opt(cmd, '' if not cmd.flag_options else 'Print help')
        v=make_version_opt(); v.describe='' if not cmd.flag_options else 'Print version'
        fos = [opt_json(h), opt_json(v)] + fos if not cmd.flag_options else fos + [opt_json(h), opt_json(v)]
    else:
        h=make_help_opt(cmd, '' if not cmd.flag_options else 'Print help')
        fos = fos + [opt_json(h)]
    return {'name': cmd.name, 'describe': cmd.describe, 'version': cmd.version,
            'aliases': cmd.aliases, 'flag_options': fos,
            'positionals': [param_json(p) for p in cmd.positionals],
            'envs': [env_json(e) for e in cmd.envs],
            'subcommands': [cmd_json(c, root) for c in cmd.subcommands],
            'command_fn': cmd.command_fn}

# ---------- compgen/completions ----------

def completion_line(shell: str, value: str, desc: str='', nospace: bool=False) -> str:
    if shell in ('bash','tcsh'):
        return value + (f" ({desc})" if desc else " ")
    if shell == 'fish':
        return value + (f"\t{desc}" if desc else "")
    if shell in ('zsh','powershell','xonsh'):
        return f"{value}\t{0 if nospace else 1}\t{value}\t{desc}\t0"
    if shell == 'nushell':
        return f"{value}\t{desc}"
    return value

def handle_compgen(argv: List[str]) -> int:
    if len(argv) < 2:
        return 0
    shell=argv[0]; file=argv[1]; words=argv[2:]
    if not words:
        return 0
    model=parse_script(file)
    # first word is command invocation name; last word is current prefix
    prefix=words[-1]
    typed=words[1:-1]
    cmd=model.root
    # symbol word skip
    if typed and model.root.symbol and typed[0].startswith('+'):
        typed=typed[1:]
    for w in typed:
        nxt=find_subcommand(cmd,w)
        if nxt:
            cmd=nxt
        else:
            break
    outs=[]
    if prefix.startswith('-') or prefix.startswith('+'):
        opts=effective_options(cmd, model.root)
        # implicit help/version
        opts2=opts+[make_help_opt(cmd)]
        if cmd is model.root: opts2.append(make_version_opt())
        for o in opts2:
            for nm in ([o.long_name] + ([o.short_name] if o.short_name else [])):
                if nm and nm.startswith(prefix): outs.append(completion_line(shell,nm,o.describe))
    else:
        # subcommands matching prefix
        if cmd.subcommands:
            for c in cmd.subcommands:
                for nm in [c.name]+c.aliases:
                    if nm.startswith(prefix): outs.append(completion_line(shell,nm,c.describe))
        else:
            # choice values for current option if previous word is an option with choices
            if typed:
                prev=typed[-1]
                opts=effective_options(cmd, model.root)
                o,_,_,_=find_option_by_token(opts,prev)
                if o and o.choice:
                    vals,_=choice_values(o.choice, model.functions)
                    for v in vals:
                        if v.startswith(prefix): outs.append(completion_line(shell,v))
            # positional choices
            for p in cmd.positionals[:1]:
                if p.choice:
                    vals,_=choice_values(p.choice, model.functions)
                    for v in vals:
                        if v.startswith(prefix): outs.append(completion_line(shell,v))
    sys.stdout.write("\n".join(outs) + ("\n" if outs else ""))
    return 0

BASH_COMPLETION = '''_argc_completer() {
    declare -a _argc_completer_words
    _argc_completer_parse_line

    export COMP_WORDBREAKS
    while IFS=$'\n' read -r line; do
        COMPREPLY+=( "$line" )
    done < <(argc --argc-compgen bash "" "${_argc_completer_words[@]}" 2>/dev/null)
}

_argc_completer_parse_line() {
    local line len i char prev_char word unbalance
    line="${COMP_LINE:0:$COMP_POINT}"
    len="${#line}"

    for ((i=0; i<len; i++)); do
        char="${line:i:1}"
        if [[ -n "$unbalance" ]]; then
            word="$word$char"
            if [[  "$unbalance" == "$char" ]]; then
                unbalance=""
            fi
        elif [[ "$char" == " " ]]; then
            if [[ "$prev_char" == "\\" ]]; then
                word="$word$char"
            elif [[ -n "$word" ]]; then
                _argc_completer_words+=( "$word" )
                word=""
            fi
        elif [[ "$char" == "'" || "$char" == '"' ]]; then
            word="$word$char"
            unbalance="$char"
        elif [[ "$char" == "\\" ]]; then
            if [[ "$prev_char" == "\\" ]]; then
                word="$word$char"
            fi
        else
            word="$word$char"
        fi
        prev_char="$char"
    done

    _argc_completer_words+=( "$word" )
}

complete -F _argc_completer -o nospace -o nosort \
    {cmds}
'''

def handle_completions(argv: List[str]) -> int:
    if not argv:
        eprint('Usage: argc --argc-completions <SHELL> [CMDS]...')
        return 1
    shell=argv[0]; cmds=['argc']+argv[1:]
    valid='bash,elvish,fish,nushell,powershell,xonsh,zsh,tcsh'.split(',')
    if shell not in valid:
        eprint('The provided shell is either invalid or missing, must be one of bash,elvish,fish,nushell,powershell,xonsh,zsh,tcsh')
        return 1
    if shell=='bash':
        sys.stdout.write(BASH_COMPLETION.format(cmds=' '.join(cmds)))
    else:
        # Compact but functional enough: all official scripts call argc --argc-compgen.
        if shell=='fish':
            sys.stdout.write('function _argc_completer\n    argc --argc-compgen fish "" (commandline -opc)\nend\ncomplete -c ' + ' -c '.join(cmds) + ' -f -a "(_argc_completer)"\n')
        elif shell=='tcsh':
            for c in cmds:
                sys.stdout.write(f"complete {c} 'p@*@`echo \"$COMMAND_LINE\" | xargs argc --argc-compgen tcsh \"\"`@@';\n")
        else:
            sys.stdout.write(f"# argc completion for {shell}\n# calls: argc --argc-compgen {shell}\n")
    return 0

# ---------- built-ins ----------

HELP_TEXT = '''A bash cli framework, also a bash-based command runner - https://github.com/sigoden/argc

USAGE:
    argc --argc-eval <FILE> <ARGS~>            Use `eval "$(argc --argc-eval "$0" "$@")"`
    argc --argc-create <RECIPES~>              Create a boilerplate argcfile
    argc --argc-run <FILE> <ARGS~>             Run an argc-based script
    argc --argc-build <FILE> <OUTPATH?>        Generate bashscript without argc dependency
    argc --argc-mangen <FILE> <OUTDIR>         Generate man pages
    argc --argc-completions <SHELL> <CMDS>     Generate shell completion scripts
    argc --argc-compgen <SHELL> <FILE> <ARGS>  Generate completion candidates
    argc --argc-export <FILE>                  Export command line definitions as json
    argc --argc-parallel <FILE> <ARGS~>        Run functions in parallel
    argc --argc-script-path                    Print current argcfile path
    argc --argc-shell-path                     Print current shell path
    argc --argc-help                           Print help information
    argc --argc-version                        Print version information
'''

def find_argcfile() -> Optional[str]:
    d=os.getcwd()
    while True:
        p=os.path.join(d,'Argcfile.sh')
        if os.path.exists(p): return p
        nd=os.path.dirname(d)
        if nd==d: return None
        d=nd

def handle_create(recipes: List[str]) -> int:
    p=os.path.join(os.getcwd(),'Argcfile.sh')
    if os.path.exists(p):
        eprint(f"Already exist {p}")
        return 1
    lines=['#!/usr/bin/env bash','', 'set -e','']
    for r in recipes:
        lines += ['# @cmd', f'{r}() {{', f'    echo TODO {r}', '}', '']
    lines += ['# See more details at https://github.com/sigoden/argc', 'eval "$(argc --argc-eval "$0" "$@")"', '']
    with open(p,'w') as f: f.write('\n'.join(lines))
    os.chmod(p,0o755)
    print('Argcfile.sh has been successfully created.')
    return 0

def handle_build(file: str, out: Optional[str]) -> int:
    if not file:
        eprint('No script file provided'); return 1
    dest=out
    if not dest:
        dest=file
    if dest and (dest.endswith('/') or os.path.isdir(dest)):
        os.makedirs(dest,exist_ok=True)
        dest=os.path.join(dest,os.path.basename(file))
    try:
        shutil.copyfile(file,dest)
        os.chmod(dest,0o755)
    except Exception as e:
        eprint(str(e)); return 1
    return 0

def handle_mangen(file: str, outdir: str) -> int:
    if not file:
        eprint('No script file provided'); return 1
    if not outdir:
        eprint('No outdir provided'); return 1
    os.makedirs(outdir,exist_ok=True)
    model=parse_script(file)
    text=help_text(model, model.root)
    name=model.root.name
    with open(os.path.join(outdir,name+'.1'),'w') as f:
        f.write(text)
    return 0

def run_argcfile(args: List[str]) -> int:
    p=find_argcfile()
    if not p:
        eprint('Argcfile not found, try `argc --argc-help` for help.')
        return 1
    return subprocess.run(['bash',p]+args).returncode

def main(argv: List[str]) -> int:
    if not argv:
        return run_argcfile([])
    cmd=argv[0]
    if cmd == '--argc-help':
        sys.stdout.write(HELP_TEXT); return 0
    if cmd == '--argc-version':
        print('argc 1.23.0'); return 0
    if cmd == '--argc-shell-path':
        print(shutil.which('bash') or '/usr/bin/bash'); return 0
    if cmd == '--argc-script-path':
        p=find_argcfile()
        if p: print(p); return 0
        eprint('Argcfile not found.'); return 1
    if cmd == '--argc-create':
        return handle_create(argv[1:])
    if cmd == '--argc-eval':
        if len(argv) < 2:
            print("echo 'Error: No script file provided'\nexit 1")
            return 0
        file=argv[1]
        model=parse_script(file)
        out=Parser(model, argv[2:]).parse()
        sys.stdout.write(out.code + ('\n' if not out.code.endswith('\n') else ''))
        return 0
    if cmd == '--argc-export':
        if len(argv) < 2:
            eprint('No script file provided'); return 1
        model=parse_script(argv[1])
        print(json.dumps(cmd_json(model.root, model.root), indent=2))
        return 0
    if cmd == '--argc-run':
        if len(argv) < 2:
            eprint('No script file provided'); return 1
        return subprocess.run(['bash', argv[1]] + argv[2:]).returncode
    if cmd == '--argc-build':
        if len(argv) < 2:
            eprint('No script file provided'); return 1
        return handle_build(argv[1], argv[2] if len(argv)>2 else None)
    if cmd == '--argc-mangen':
        if len(argv) < 2:
            eprint('No script file provided'); return 1
        return handle_mangen(argv[1], argv[2] if len(argv)>2 else '')
    if cmd == '--argc-completions':
        return handle_completions(argv[1:])
    if cmd == '--argc-compgen':
        return handle_compgen(argv[1:])
    if cmd == '--argc-parallel':
        # Direct external fallback: not able to call parent shell functions. Keep successful no-op-ish behavior.
        # The generated eval installs a shell function that implements the real behavior.
        return 0
    # Anything else is Argcfile runner mode.
    return run_argcfile(argv)

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
